"""Lexer and recursive-descent parser for the minisql SELECT subset."""
from dataclasses import dataclass
import re


@dataclass(frozen=True)
class Expr:
    kind: str
    value: object = None
    args: tuple = ()


@dataclass(frozen=True)
class SelectItem:
    expr: Expr
    alias: str = None
    text: str = ""


@dataclass(frozen=True)
class OrderItem:
    expr: Expr
    descending: bool = False
    text: str = ""


@dataclass(frozen=True)
class Query:
    distinct: bool
    columns: tuple
    table: str
    where: object = None
    group_by: tuple = ()
    having: object = None
    order_by: tuple = ()
    limit: object = None
    offset: int = 0


class ParseError(ValueError):
    pass


_KEYWORDS = set("SELECT DISTINCT FROM WHERE GROUP BY HAVING ORDER LIMIT OFFSET AS ASC DESC AND OR NOT IS NULL IN BETWEEN LIKE TRUE FALSE".split())
_TOKEN = re.compile(r"\s+|(?:--[^\n]*(?:\n|$))|(?:/\*[\s\S]*?\*/)|(?:'(?:''|[^'])*')|(?:\"(?:\"\"|[^\"])*\")|(?:[A-Za-z_][A-Za-z_0-9]*)|(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)|(?:<=|>=|<>|!=|\|\|)|.")


def _lex(sql):
    out=[]; pos=0
    while pos < len(sql):
        m=_TOKEN.match(sql,pos)
        if not m: raise ParseError("invalid SQL")
        raw=m.group(); pos=m.end()
        if raw.isspace() or raw.startswith('--') or raw.startswith('/*'): continue
        start=m.start()
        if raw[0] == "'": out.append(("STRING", raw[1:-1].replace("''", "'"), start, pos))
        elif raw[0] == '"': out.append(("QIDENT", raw[1:-1].replace('""','"'), start, pos))
        elif re.fullmatch(r"[A-Za-z_][A-Za-z_0-9]*",raw): out.append(("KW" if raw.upper() in _KEYWORDS else "IDENT",raw,start,pos))
        elif re.fullmatch(r"(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)",raw): out.append(("NUMBER",raw,start,pos))
        else: out.append(("SYM",raw,start,pos))
    out.append(("EOF", "", len(sql),len(sql)))
    return out


class _Parser:
    def __init__(self, sql): self.sql=sql; self.ts=_lex(sql); self.i=0
    def t(self): return self.ts[self.i]
    def is_kw(self,s): return self.t()[0]=="KW" and self.t()[1].upper()==s
    def eat(self): x=self.t(); self.i+=1; return x
    def accept_kw(self,s):
        if self.is_kw(s): self.eat(); return True
        return False
    def accept(self,s):
        if self.t()[1]==s: self.eat(); return True
        return False
    def expect_kw(self,s):
        if not self.accept_kw(s): raise ParseError("expected " + s)
    def expect(self,s):
        if not self.accept(s): raise ParseError("expected " + s)
    def identifier(self):
        t=self.t()
        if t[0] in ("IDENT","QIDENT"): self.eat(); return t[1]
        raise ParseError("expected name")
    def parse(self):
        self.expect_kw("SELECT"); distinct=self.accept_kw("DISTINCT")
        if self.accept('*'): cols=()
        else:
            cols=[]
            while True:
                st=self.t()[2]; e=self.expr(); alias=None
                if self.accept_kw("AS"): alias=self.identifier()
                elif self.t()[0] in ("IDENT","QIDENT"): alias=self.identifier()
                end=self.ts[self.i-1][3]
                cols.append(SelectItem(e,alias,self.sql[st:end].strip()))
                if not self.accept(','): break
            cols=tuple(cols)
        self.expect_kw("FROM"); table=self.identifier()
        where=None; groups=(); having=None; orders=(); limit=None; offset=0
        if self.accept_kw("WHERE"): where=self.expr()
        if self.accept_kw("GROUP"):
            self.expect_kw("BY"); groups=self.expr_list()
        if self.accept_kw("HAVING"): having=self.expr()
        if self.accept_kw("ORDER"):
            self.expect_kw("BY"); arr=[]
            while True:
                st=self.t()[2]; e=self.expr(); desc=self.accept_kw("DESC")
                if not desc: self.accept_kw("ASC")
                end=self.ts[self.i-1][3]
                arr.append(OrderItem(e,desc,self.sql[st:end].strip()))
                if not self.accept(','): break
            orders=tuple(arr)
        if self.accept_kw("LIMIT"):
            limit=self.integer()
            if self.accept_kw("OFFSET"): offset=self.integer()
        elif self.accept_kw("OFFSET"):
            offset=self.integer()
        self.accept(';')
        if self.t()[0]!="EOF": raise ParseError("unexpected token: " + self.t()[1])
        return Query(distinct,cols,table,where,groups,having,orders,limit,offset)
    def integer(self):
        t=self.t()
        if t[0]!="NUMBER" or '.' in t[1]: raise ParseError("expected integer")
        self.eat(); return int(t[1])
    def expr_list(self):
        result=[]
        while True:
            result.append(self.expr())
            if not self.accept(','): return tuple(result)
    def expr(self): return self.or_expr()
    def or_expr(self):
        x=self.and_expr()
        while self.accept_kw("OR"): x=Expr('binary','OR',(x,self.and_expr()))
        return x
    def and_expr(self):
        x=self.not_expr()
        while self.accept_kw("AND"): x=Expr('binary','AND',(x,self.not_expr()))
        return x
    def not_expr(self):
        if self.accept_kw("NOT"): return Expr('unary','NOT',(self.not_expr(),))
        return self.compare()
    def compare(self):
        x=self.concat()
        while True:
            if self.accept_kw("IS"):
                neg=self.accept_kw("NOT"); self.expect_kw("NULL"); x=Expr('IS NOT NULL' if neg else 'IS NULL',args=(x,)); continue
            neg=False
            if self.is_kw('NOT') and self.i+1<len(self.ts) and self.ts[self.i+1][0]=='KW' and self.ts[self.i+1][1].upper() in ('IN','BETWEEN','LIKE'):
