            if self.accept_kw('IN'):
                self.expect('('); vals=self.expr_list(); self.expect(')'); x=Expr('NOT IN' if neg else 'IN',args=(x,)+vals); continue
            if self.accept_kw('BETWEEN'):
                lo=self.concat(); self.expect_kw('AND'); hi=self.concat(); x=Expr('NOT BETWEEN' if neg else 'BETWEEN',args=(x,lo,hi)); continue
            if self.accept_kw('LIKE'):
                x=Expr('NOT LIKE' if neg else 'LIKE',args=(x,self.concat())); continue
            if neg: raise ParseError("expected IN, BETWEEN, or LIKE after NOT")
            op=self.t()[1]
            if op in ('=','!=','<>','<','<=','>','>='):
                self.eat(); x=Expr('binary',op,(x,self.concat())); continue
            break
        return x
    def concat(self):
        x=self.add()
        while self.accept('||'): x=Expr('binary','||',(x,self.add()))
        return x
    def add(self):
        x=self.mul()
        while self.t()[1] in ('+','-'):
            op=self.eat()[1]; x=Expr('binary',op,(x,self.mul()))
        return x
    def mul(self):
        x=self.unary()
        while self.t()[1] in ('*','/'):
            op=self.eat()[1]; x=Expr('binary',op,(x,self.unary()))
        return x
    def unary(self):
        if self.accept('-'): return Expr('unary','-',(self.unary(),))
        return self.atom()
    def atom(self):
        t=self.t()
        if self.accept('('): x=self.expr(); self.expect(')'); return x
        if t[0]=='STRING': self.eat(); return Expr('literal',t[1])
        if t[0]=='NUMBER':
            self.eat(); return Expr('literal',float(t[1]) if '.' in t[1] else int(t[1]))
        if self.accept_kw('NULL'): return Expr('literal',None)
        if self.accept_kw('TRUE'): return Expr('literal',True)
        if self.accept_kw('FALSE'): return Expr('literal',False)
        if t[0] in ('IDENT','QIDENT'):
            name=self.eat()[1]
            if self.accept('('):
                if self.accept('*'): args=(Expr('star'),); self.expect(')')
                elif self.accept(')'): args=()
                else: args=self.expr_list(); self.expect(')')
                return Expr('call',name.upper(),args)
            return Expr('name',name)
        if self.accept('*'): return Expr('star')
        raise ParseError("expected expression")


def parse(sql):
    """Parse one SELECT statement, raising ParseError on invalid syntax."""
    if not isinstance(sql,str): raise ParseError("query must be a string")
    return _Parser(sql).parse()

