"""Run SQL SELECT queries against CSV files. See SPEC.md."""

import csv
import os
import re
from decimal import Decimal, ROUND_HALF_UP

from .parser import parse, Expr
from .expr import evaluate, contains_aggregate, validate_aggregates


class QueryError(Exception):
    """Raised for any problem with a query."""


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    try:
        q = parse(sql)
        path = os.path.join(os.fspath(directory), q.table + ".csv")
        with open(path, newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            headers = next(reader, None)
            if headers is None:
                raise QueryError("table has no header")
            rows = []
            for fields in reader:
                row = {}
                for i, name in enumerate(headers):
                    value = fields[i] if i < len(fields) else ""
                    row[name.casefold()] = _convert(value)
                rows.append(row)
        if q.where is not None:
            rows = [r for r in rows if _truth(_eval(q.where, r, headers)) is True]
        for expr in [x.expr for x in q.columns] + [q.having] + [o.expr for o in q.order_by]:
            if expr is not None: validate_aggregates(expr)
        aggregate = any(contains_aggregate(x.expr) for x in q.columns) or contains_aggregate(q.having) or any(contains_aggregate(o.expr) for o in q.order_by)
        grouped = bool(q.group_by) or aggregate
        if grouped:
            for item in q.columns:
                _validate_grouping(item.expr, q.group_by)
            if q.having is not None: _validate_grouping(q.having, q.group_by)
            for order in q.order_by: _validate_grouping(order.expr, q.group_by)
        if grouped:
            buckets = {}
            if q.group_by:
                for row in rows:
                    key = tuple(evaluate(e, row, headers) for e in q.group_by)
                    buckets.setdefault(key, []).append(row)
            else:
                buckets[()] = rows
            contexts = [(key, group, group[0] if group else {}) for key, group in buckets.items()]
            contexts = [c for c in contexts if q.having is None or _truth(evaluate(q.having, c[2], headers, c[1])) is True]
        else:
            contexts = [((), [r], r) for r in rows]
        items = list(q.columns) if q.columns else [type("I", (), {"expr": Expr("name", h), "alias": None, "text": h})() for h in headers]
        names = []
        for item in items:
            if item.alias:
                names.append(item.alias)
            elif item.expr.kind == "name":
                names.append(_header(headers, item.expr.value))
            else:
                names.append(item.text)
        output = []
        for _, group, row in contexts:
            vals = tuple(evaluate(i.expr, row, headers, group) for i in items)
            output.append([vals, row, group])
        if q.distinct:
            seen = set(); unique = []
            for rec in output:
                key = tuple(_hashable(x) for x in rec[0])
                if key not in seen: seen.add(key); unique.append(rec)
            output = unique
        if q.order_by:
            # Stable least-significant-key-first sorting supports mixed ASC/DESC and NULL ordering.
            for order in reversed(q.order_by):
                def key(rec):
                    expr = order.expr
                    if expr.kind == "literal" and isinstance(expr.value, int) and not isinstance(expr.value, bool):
                        idx = expr.value - 1
                        val = rec[0][idx] if 0 <= idx < len(rec[0]) else None
                    elif expr.kind == "name" and expr.value.casefold() in {n.casefold() for n in names}:
                        idx = next(i for i,n in enumerate(names) if n.casefold()==expr.value.casefold()); val=rec[0][idx]
                    else: val = evaluate(expr, rec[1], headers, rec[2])
                    return (val is not None, val)
                try: output.sort(key=key, reverse=order.descending)
                except (TypeError, ValueError) as e: raise QueryError("incomparable ORDER BY values") from e
        start = q.offset or 0
        output = output[start:None if q.limit is None else start + q.limit]
        return type("Result", (), {"columns": names, "rows": [tuple(r[0]) for r in output]})()
    except QueryError:
        raise
    except Exception as exc:
        raise QueryError(str(exc)) from exc


def _convert(s):
    if s == "": return None
    if re.fullmatch(r"-?[0-9]+", s): return int(s)
    if re.fullmatch(r"-?(?:[0-9]+\.[0-9]*|[0-9]*\.[0-9]+)", s): return float(s)
    return s


def _header(headers, name):
    matches = [h for h in headers if h.casefold() == name.casefold()]
    if not matches: raise QueryError("unknown column: " + name)
    return matches[0]


def _truth(v):
    if v is not None and not isinstance(v, bool): raise QueryError("condition must be boolean")
    return v


def _contains_agg(e):
    return bool(e and e.kind == "call" and e.value in ("COUNT", "SUM", "AVG", "MIN", "MAX")) or bool(e and any(_contains_agg(a) for a in e.args))


def _eval(e, row, headers, group=None):
    if e is None: return None
    k, v, a = e.kind, e.value, e.args
    if k == "literal": return v
    if k == "name": return row.get(_header(headers, v).casefold())
    if k == "star": return None
    if k == "unary":
        x = _eval(a[0], row, headers, group)
        if v == "NOT": return None if x is None else not _truth(x)
        if x is None: return None
        if isinstance(x, bool) or not isinstance(x, (int,float)): raise QueryError("unary minus requires a number")
        return -x
    if k == "call":
        fn = v.upper()
        if fn in ("COUNT","SUM","AVG","MIN","MAX"):
            if group is None: raise QueryError("aggregate outside grouped query")
            if fn == "COUNT" and a[0].kind == "star": return len(group)
            vals = [_eval(a[0], r, headers) for r in group]; vals = [x for x in vals if x is not None]
            if fn == "COUNT": return len(vals)
            if not vals: return None
            if fn == "SUM":
                if any(isinstance(x,bool) or not isinstance(x,(int,float)) for x in vals): raise QueryError("SUM requires numbers")
                return sum(vals)
            if fn == "AVG":
                if any(isinstance(x,bool) or not isinstance(x,(int,float)) for x in vals): raise QueryError("AVG requires numbers")
                return float(sum(vals)/len(vals))
            try: return min(vals) if fn == "MIN" else max(vals)
            except TypeError as ex: raise QueryError("incomparable aggregate values") from ex
        vals = [_eval(x,row,headers,group) for x in a]
        if fn == "COALESCE": return next((x for x in vals if x is not None), None)
        if any(x is None for x in vals): return None
        try:
            if fn == "LOWER" and len(vals)==1 and isinstance(vals[0],str): return vals[0].lower()
            if fn == "UPPER" and len(vals)==1 and isinstance(vals[0],str): return vals[0].upper()
            if fn == "LENGTH" and len(vals)==1 and isinstance(vals[0],str): return len(vals[0])
            if fn == "ABS" and len(vals)==1 and _number(vals[0]): return abs(vals[0])
            if fn == "ROUND" and len(vals) in (1,2) and _number(vals[0]):
                if len(vals)==1: return int(Decimal(str(vals[0])).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
                if not isinstance(vals[1],int) or isinstance(vals[1],bool): raise QueryError("ROUND precision must be integer")
                return float(Decimal(str(vals[0])).quantize(Decimal(1).scaleb(-vals[1]), rounding=ROUND_HALF_UP))
        except (ValueError, ArithmeticError): return None
        raise QueryError("unknown function or invalid arguments: " + fn)
    if k == "binary":
        op = v.upper()
        if op == "AND":
            x=_truth(_eval(a[0],row,headers,group)); y=_truth(_eval(a[1],row,headers,group))
            return False if x is False or y is False else (None if x is None or y is None else True)
        if op == "OR":
            x=_truth(_eval(a[0],row,headers,group)); y=_truth(_eval(a[1],row,headers,group))
            return True if x is True or y is True else (None if x is None or y is None else False)
        x=_eval(a[0],row,headers,group)
        if op in ("IS NULL","IS NOT NULL"): return (x is None) ^ (op == "IS NOT NULL")
        if op in ("IN","NOT IN"):
            ys=[_eval(t,row,headers,group) for t in a[1:]]
            z = True if any(_compare(x,y,"=") is True for y in ys) else (None if x is None or any(y is None for y in ys) else False)
            return (None if z is None else not z) if op == "NOT IN" else z
        if op in ("BETWEEN","NOT BETWEEN"):
            lo=_eval(a[1],row,headers,group); hi=_eval(a[2],row,headers,group)
            z=_logic_and(_compare(x,lo,">="),_compare(x,hi,"<=")); return (None if z is None else not z) if op=="NOT BETWEEN" else z
        y=_eval(a[1],row,headers,group)
        if op in ("LIKE","NOT LIKE"):
            if x is None or y is None: return None
            if not isinstance(x,str) or not isinstance(y,str): raise QueryError("LIKE requires strings")
            pat="^"+"".join(".*" if c=="%" else "." if c=="_" else re.escape(c) for c in y)+"$"; z=bool(re.match(pat,x,dotall=True)); return not z if op=="NOT LIKE" else z
        if op in ("=","!=","<>","<",">","<=",">="): return _compare(x,y,op)
        if x is None or y is None: return None
        if op=="||": return str(x)+str(y)
        if not _number(x) or not _number(y): raise QueryError("arithmetic requires numbers")
        if op=="+": return x+y
        if op=="-": return x-y
        if op=="*": return x*y
        if op=="/": return None if y==0 else x/y
    raise QueryError("invalid expression")


def _number(x): return isinstance(x,(int,float)) and not isinstance(x,bool)
def _logic_and(x,y): return False if x is False or y is False else None if x is None or y is None else True
def _compare(x,y,op):
    if x is None or y is None: return None
    if _number(x) and _number(y): pass
    elif isinstance(x,str) and isinstance(y,str): pass
    elif isinstance(x,bool) and isinstance(y,bool): pass
    else: raise QueryError("incompatible comparison values")
    try: return {"=":lambda:x==y,"!=":lambda:x!=y,"<>":lambda:x!=y,"<":lambda:x<y,">":lambda:x>y,"<=":lambda:x<=y,">=":lambda:x>=y}[op]()
    except TypeError as ex: raise QueryError("incompatible comparison values") from ex
def _hashable(x):
    try: hash(x); return x
    except TypeError: return repr(x)


def _same_expr(a, b):
    return a == b


def _validate_grouping(expr, groups, inside_aggregate=False):
    if expr is None: return
    if any(_same_expr(expr, g) for g in groups): return
    if expr.kind == "call" and expr.value.upper() in ("COUNT", "SUM", "AVG", "MIN", "MAX"):
        return
    if expr.kind == "name" and not inside_aggregate and not any(g == expr for g in groups):
        raise QueryError("column must appear in GROUP BY or an aggregate")
    for child in expr.args:
        _validate_grouping(child, groups, inside_aggregate)

