"""Expression evaluation for the small SQL dialect.

The parser deliberately keeps expressions as a compact ``Expr(kind, value,
args)`` tree.  This module contains the value semantics shared by filtering,
projection, grouping and ordering.
"""
from decimal import Decimal, ROUND_HALF_UP
import re


def _error(message):
    # Imported lazily to avoid a package initialization cycle.
    from . import QueryError
    raise QueryError(message)


def contains_aggregate(expr):
    """Return whether *expr* contains an aggregate function call."""
    if getattr(expr, "kind", None) == "call" and expr.value.upper() in _AGGREGATES:
        return True
    return any(contains_aggregate(arg) for arg in getattr(expr, "args", ()))


_AGGREGATES = {"COUNT", "SUM", "AVG", "MIN", "MAX"}


def validate_aggregates(expr, inside=False):
    """Reject nested aggregates, and return whether an aggregate occurs."""
    kind = getattr(expr, "kind", None)
    is_agg = kind == "call" and expr.value.upper() in _AGGREGATES
    if is_agg and inside:
        _error("aggregate functions cannot be nested")
    found = is_agg
    for arg in getattr(expr, "args", ()):
        found = validate_aggregates(arg, inside or is_agg) or found
    return found


def _lookup(name, row, columns):
    if hasattr(row, "keys"):
        for key in row:
            if str(key).casefold() == name.casefold():
                return row[key]
    else:
        for i, key in enumerate(columns or ()):
            if str(key).casefold() == name.casefold():
                try:
                    return row[i]
                except (IndexError, TypeError):
                    break
    _error("unknown column: " + name)


def _truth(value):
    if value is None:
        return None
    if isinstance(value, bool):
        return value
    _error("logical operators require boolean values")


def _numeric(v):
    return isinstance(v, (int, float)) and not isinstance(v, bool)


def _compare(a, b):
    if _numeric(a) and _numeric(b):
        return (a > b) - (a < b)
    if type(a) is type(b) and isinstance(a, (str, bool)):
        return (a > b) - (a < b)
    _error("incompatible values in comparison")


def _aggregate(expr, group, columns):
    name = expr.value.upper()
    args = expr.args
    if name == "COUNT":
        if len(args) != 1:
            _error("COUNT expects one argument")
        if getattr(args[0], "kind", None) == "star":
            return len(group)
        return sum(evaluate(args[0], row, columns, None) is not None for row in group)
    if len(args) != 1:
        _error(name + " expects one argument")
    values = [evaluate(args[0], row, columns, None) for row in group]
    values = [v for v in values if v is not None]
    if not values:
        return None
    if name in ("SUM", "AVG"):
        if not all(_numeric(v) for v in values):
            _error(name + " requires numeric values")
        if name == "SUM":
            return sum(values)
        return float(sum(values) / len(values))
    result = values[0]
    for value in values[1:]:
        result = (min if name == "MIN" else max)(result, value, key=_SortKey)
    return result


class _SortKey:
    """Placeholder key wrapper is not used; min/max comparison is handled below."""
    def __init__(self, value): self.value = value
    def __lt__(self, other): return _compare(self.value, other.value) < 0


def evaluate(expr, row=None, columns=None, group=None):
    """Evaluate an expression for a row, optionally in an aggregate group.

    ``row`` may be a header-aligned tuple/list or a mapping. ``group`` is a
    sequence of rows in the same representation.
    """
    kind, value, args = expr.kind, expr.value, expr.args
    if kind == "literal":
        return value
    if kind == "name":
        return _lookup(value, row, columns)
    if kind == "star":
        _error("* is only valid in COUNT(*) or SELECT *")
    if kind == "call":
        name = value.upper()
        if name in _AGGREGATES:
            if group is None:
                _error("aggregate function used outside a group")
            return _aggregate(expr, group, columns)
        if name == "COALESCE":
            if not args:
                _error("COALESCE expects at least one argument")
            for arg in args:
                result = evaluate(arg, row, columns, group)
                if result is not None:
                    return result
            return None
        arities = {"LOWER": 1, "UPPER": 1, "LENGTH": 1, "ABS": 1, "ROUND": (1, 2)}
        if name not in arities:
            _error("unknown function: " + value)
        expected = arities[name]
        if (len(args) not in expected if isinstance(expected, tuple) else len(args) != expected):
            _error("wrong number of arguments to " + name)
        vals = [evaluate(a, row, columns, group) for a in args]
        if any(v is None for v in vals):
            return None
        x = vals[0]
        if name in ("LOWER", "UPPER", "LENGTH"):
            if not isinstance(x, str): _error(name + " requires a string")
            return x.lower() if name == "LOWER" else x.upper() if name == "UPPER" else len(x)
        if not _numeric(x): _error(name + " requires a number")
        if name == "ABS": return abs(x)
        if len(vals) == 1:
            return int(Decimal(str(x)).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
        n = vals[1]
        if not isinstance(n, int) or isinstance(n, bool): _error("ROUND precision must be an integer")
        quantum = Decimal(1).scaleb(-n)
        return float(Decimal(str(x)).quantize(quantum, rounding=ROUND_HALF_UP))
    if kind == "unary":
        x = evaluate(args[0], row, columns, group)
        if value == "NOT":
            t = _truth(x)
            return None if t is None else not t
        if value == "-":
            if x is None: return None
            if not _numeric(x): _error("unary - requires a number")
            return -x
        _error("unknown unary operator: " + str(value))
    if kind == "binary":
        op = value.upper()
        left = evaluate(args[0], row, columns, group)
        if op == "AND":
            l = _truth(left)
            if l is False: return False
            r = _truth(evaluate(args[1], row, columns, group))
            return False if r is False else (True if l is True and r is True else None)
        if op == "OR":
            l = _truth(left)
            if l is True: return True
            r = _truth(evaluate(args[1], row, columns, group))
            return True if r is True else (False if l is False and r is False else None)
        right = evaluate(args[1], row, columns, group)
        if left is None or right is None: return None
        if op == "||": return str(left) + str(right)
        if op in ("=", "!=", "<>", "<", "<=", ">", ">="):
            c = _compare(left, right)
            return {"=": c == 0, "!=": c != 0, "<>": c != 0, "<": c < 0,
                    "<=": c <= 0, ">": c > 0, ">=": c >= 0}[op]
        if op in ("+", "-", "*", "/"):
            if not _numeric(left) or not _numeric(right): _error("arithmetic requires numeric values")
            if op == "/": return None if right == 0 else left / right
            if op == "+": return left + right
            if op == "-": return left - right
            return left * right
        _error("unknown operator: " + value)
    if kind in ("IS NULL", "IS NOT NULL"):
        result = evaluate(args[0], row, columns, group) is None
        return result if kind == "IS NULL" else not result
    if kind in ("IN", "NOT IN"):
        lhs = evaluate(args[0], row, columns, group)
        vals = [evaluate(a, row, columns, group) for a in args[1:]]
        if any(v is not None and lhs is not None and _compare(lhs, v) == 0 for v in vals): result = True
        elif lhs is None or any(v is None for v in vals): result = None
        else: result = False
        return (None if result is None else not result) if kind == "NOT IN" else result
    if kind in ("BETWEEN", "NOT BETWEEN"):
        x, lo, hi = (evaluate(a, row, columns, group) for a in args)
        if x is None or lo is None or hi is None: result = None
        else: result = _compare(lo, x) <= 0 and _compare(x, hi) <= 0
        return (None if result is None else not result) if kind == "NOT BETWEEN" else result
    if kind in ("LIKE", "NOT LIKE"):
        x, pattern = (evaluate(a, row, columns, group) for a in args)
        if x is None or pattern is None: result = None
        elif not isinstance(x, str) or not isinstance(pattern, str): _error("LIKE requires strings")
        else:
            regex = "".join(".*" if c == "%" else "." if c == "_" else re.escape(c) for c in pattern)
            result = re.fullmatch(regex, x, flags=re.DOTALL) is not None
        return (None if result is None else not result) if kind == "NOT LIKE" else result
    _error("unknown expression")
